import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        max_val = max(a)
        if all(x == max_val for x in a):
            results.append("-1")
            continue

        found_index = -1
        for i in range(n):
            if a[i] == max_val:
                if i > 0 and a[i-1] != max_val:
                    found_index = i + 1
                    break
                if i < n - 1 and a[i+1] != max_val:
                    found_index = i + 1

        if found_index != -1:
            results.append(str(found_index))
        else:
            results.append("-1")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
